import {createStudy,canvasSurface,seededRandom,clamp,lerp,downloadCanvas} from './core.js';
const study=createStudy({id:15,title:'Orbital Assembly',category:'Physics / Scale',accent:'#dfff00',background:'#17112c',foreground:'#f2ead5'});
const canvas=document.querySelector('#orbital-canvas'),surface=canvasSurface(canvas,{maxDpr:1.5});
const names=['The central star','Cinder','Hush','Vela','Solace','Halo','Drift','Lumen','Elsewhere'];
const palette=['#f2ead5','#f57864','#e3b781','#9583d1','#dfff00','#6e9bce','#e6b4d2','#afa6dc','#c5d5bd'];
let bodies=[],stars=[],selected=0,zoomBase=1,speed=1,scrollProgress=0,camera={x:0,y:0,zoom:1};
function reset(){const rand=seededRandom(15015);bodies=[{x:0,y:0,vx:0,vy:0,mass:240,r:37,color:palette[0],trail:[]}];for(let i=1;i<=8;i++){const distance=70+i*34,angle=i*2.399963+rand()*.2,velocity=Math.sqrt(450*240/distance);bodies.push({x:Math.cos(angle)*distance,y:Math.sin(angle)*distance,vx:-Math.sin(angle)*velocity,vy:Math.cos(angle)*velocity,mass:1.5+rand()*4,r:5+i*1.15,color:palette[i],trail:[]})}stars=Array.from({length:170},()=>({x:rand(),y:rand(),r:rand()*.9+.2,alpha:rand()*.5+.15}));selected=0;camera={x:0,y:0,zoom:zoomBase};document.querySelector('#orbital-body').value='0';document.querySelector('#orbital-name').textContent=names[0].toUpperCase();draw();}
function project(p){const{width:w,height:h}=surface;const scale=Math.min(w*.84,h*.88)/800*camera.zoom;return{x:w*(w<600?.62:.65)+(p.x-camera.x)*scale,y:h*.49+(p.y-camera.y)*scale,scale}}
function simulate(dt){if(dt<=0)return;const whole=dt*speed,steps=Math.ceil(whole/.014),t=whole/steps,G=450;for(let sub=0;sub<steps;sub++){const accelerations=bodies.map(()=>({x:0,y:0}));for(let i=0;i<bodies.length;i++)for(let j=i+1;j<bodies.length;j++){const a=bodies[i],b=bodies[j],dx=b.x-a.x,dy=b.y-a.y,d2=dx*dx+dy*dy+64,inv=1/(d2*Math.sqrt(d2));accelerations[i].x+=G*b.mass*dx*inv;accelerations[i].y+=G*b.mass*dy*inv;accelerations[j].x-=G*a.mass*dx*inv;accelerations[j].y-=G*a.mass*dy*inv}for(let i=0;i<bodies.length;i++){const b=bodies[i],f=accelerations[i];b.vx=clamp(b.vx+f.x*t,-220,220);b.vy=clamp(b.vy+f.y*t,-220,220);b.x+=b.vx*t;b.y+=b.vy*t}}for(const b of bodies){b.trail.push({x:b.x,y:b.y});if(b.trail.length>165)b.trail.shift()}}
function draw(){const{ctx,width:w,height:h}=surface;if(!ctx)return;ctx.clearRect(0,0,w,h);ctx.fillStyle='#17112c';ctx.fillRect(0,0,w,h);for(const star of stars){ctx.beginPath();ctx.arc(star.x*w,star.y*h,star.r,0,Math.PI*2);ctx.fillStyle=`rgba(242,234,213,${star.alpha})`;ctx.fill()}const center=project(bodies[0]);for(let i=1;i<bodies.length;i++){const p=bodies[i],orb=project(p);ctx.beginPath();p.trail.forEach((pos,j)=>{const q=project(pos);j?ctx.lineTo(q.x,q.y):ctx.moveTo(q.x,q.y)});ctx.strokeStyle=p.color+'77';ctx.lineWidth=i===selected?1.3:.65;ctx.stroke();if(p.trail.length<10){const radius=Math.hypot(p.x-bodies[0].x,p.y-bodies[0].y)*orb.scale;ctx.beginPath();ctx.ellipse(center.x,center.y,radius,radius,0,0,Math.PI*2);ctx.strokeStyle='#afa6dc25';ctx.lineWidth=.6;ctx.stroke()}}for(let i=0;i<bodies.length;i++){const b=bodies[i],p=project(b),radius=clamp(b.r*p.scale,i===0?17:3,150);if(i===0){const glow=ctx.createRadialGradient(p.x,p.y,radius*.4,p.x,p.y,radius*3.2);glow.addColorStop(0,'#f2ead535');glow.addColorStop(1,'#f2ead500');ctx.beginPath();ctx.arc(p.x,p.y,radius*3.2,0,Math.PI*2);ctx.fillStyle=glow;ctx.fill()}ctx.beginPath();ctx.arc(p.x,p.y,radius,0,Math.PI*2);const gradient=ctx.createRadialGradient(p.x-radius*.3,p.y-radius*.35,0,p.x,p.y,radius);gradient.addColorStop(0,b.color);gradient.addColorStop(1,i===0?'#bcac90':'#322445');ctx.fillStyle=gradient;ctx.fill();if(i===selected){ctx.beginPath();ctx.arc(p.x,p.y,radius+9,0,Math.PI*2);ctx.strokeStyle='#dfff00';ctx.lineWidth=.8;ctx.setLineDash([3,5]);ctx.stroke();ctx.setLineDash([]);ctx.font='8px Geist, sans-serif';ctx.fillStyle='#dfff00';ctx.fillText(String(i).padStart(2,'0')+' / '+names[i].toUpperCase(),p.x+radius+15,p.y+3)}}}
function frame({dt}){simulate(dt);const target=bodies[selected]||bodies[0];const zoom=clamp(zoomBase*(1+scrollProgress*1.6),.5,5);const focus=(zoom-1)/4;const tx=target.x*clamp(focus,0,1),ty=target.y*clamp(focus,0,1);if(dt>0){camera.x=lerp(camera.x,tx,.045);camera.y=lerp(camera.y,ty,.045);camera.zoom=lerp(camera.zoom,zoom,.055)}draw();}
document.querySelector('#orbital-body').addEventListener('change',event=>{selected=+event.target.value;document.querySelector('#orbital-name').textContent=names[selected].toUpperCase();study.invalidate()});
document.querySelector('#orbital-scale').addEventListener('input',event=>{zoomBase=+event.target.value;document.querySelector('#orbital-scale-value').textContent=zoomBase.toFixed(1)+'×';if(!study.running())camera.zoom=zoomBase;study.invalidate()});
document.querySelector('#orbital-speed').addEventListener('input',event=>{speed=+event.target.value;document.querySelector('#orbital-speed-value').textContent=speed.toFixed(2).replace(/0$/,'')+'×';study.invalidate()});
document.querySelector('#orbital-impulse').addEventListener('click',()=>{if(selected===0){selected=4;document.querySelector('#orbital-body').value='4';document.querySelector('#orbital-name').textContent=names[4].toUpperCase()}const b=bodies[selected];b.vx+=8;b.vy-=5;b.x+=2;study.invalidate()});
canvas.addEventListener('pointerup',event=>{const r=canvas.getBoundingClientRect(),x=event.clientX-r.left,y=event.clientY-r.top;let found=-1,best=35;for(let i=0;i<bodies.length;i++){const p=project(bodies[i]),d=Math.hypot(x-p.x,y-p.y);if(d<best){found=i;best=d}}if(found>=0){selected=found;document.querySelector('#orbital-body').value=String(found);document.querySelector('#orbital-name').textContent=names[found].toUpperCase();study.invalidate()}});
const scroll=()=>{scrollProgress=clamp((72-document.querySelector('.orbital-story').getBoundingClientRect().top)/Math.max(1,document.querySelector('.orbital-story').offsetHeight-surface.height),0,1);study.invalidate()};window.addEventListener('scroll',scroll,{passive:true});study.cleanup(()=>window.removeEventListener('scroll',scroll));
study.setReset(()=>{zoomBase=1;speed=1;document.querySelector('#orbital-scale').value='1';document.querySelector('#orbital-scale-value').textContent='1.0×';document.querySelector('#orbital-speed').value='1';document.querySelector('#orbital-speed-value').textContent='1.0×';reset()});study.setExport(()=>downloadCanvas(canvas,'15-orbital-assembly.png'));study.onResize(()=>{surface.resize();if(!bodies.length)reset();else draw()});study.onFrame(frame);study.cleanup(()=>surface.dispose());reset();scroll();
